import type { Ayah, Lang } from './types';
import data from './ayat.generated.json';

/** Generated by scripts/build-ayat.mjs: never edit Qur'anic text by hand. */
export const AYAT = data as Ayah[];

const byId = new Map(AYAT.map((a) => [a.id, a]));
export const ayah = (id: string): Ayah => {
  const a = byId.get(id);
  if (!a) throw new Error(`Unknown ayah ${id}`);
  return a;
};

export const DAILY_POOL = AYAT.filter((a) => a.tags.includes('daily'));

const UR_DIGITS = '۰۱۲۳۴۵۶۷۸۹';
export const urDigits = (s: string | number) => String(s).replace(/\d/g, (d) => UR_DIGITS[+d]);

/** "Az-Zumar 39:53" or "سورۃ الزمر ۳۹:۵۳" */
export function ayahRef(a: Pick<Ayah, 'surah' | 'from' | 'to' | 'surahName'>, lang: Lang): string {
  const v = a.to !== a.from ? `${a.from}–${a.to}` : `${a.from}`;
  return lang === 'ur'
    ? `سورۃ ${a.surahName.ar} ${urDigits(`${a.surah}:${v}`)}`
    : `${a.surahName.en} ${a.surah}:${v}`;
}
